void Editor::smokeRuntimePreferences(bool persist){

    if(persist && (recoveryDirectory_.empty() || recoveryDirectory_.parent_path()!=palettePreferencePath().parent_path()))throw std::runtime_error("Persistence check requires isolated preference/recovery root");

    smoke_=!persist;homeOpen_=false;documentOpen_=true;pending_=Pending::None;setBounds({0,0,1280,960});refresh();

    const auto original=runtimePreferences_;const auto history=document.historySize(),revision=document.revision();const auto pixels=document.pixels();

    auto row=[&](const std::string& key)->ui::Widget*{for(std::size_t i=0;i<preferences::catalog().size();++i)if(key==preferences::catalog()[i].id)return preferenceRows_[i];throw std::runtime_error("Preference row missing");};

    showPreferences();preferenceTabs_[5]->Click();

    if(persist){

      if(!applyPreferences())throw std::runtime_error("Initial preference disk save failed: "+utf8Text(status_));

      const auto path=palettePreferencePath().parent_path()/"editor-preferences.txt";

      const auto saved=runtimePreferences_.values;

      const HANDLE locked=CreateFileW(path.c_str(),GENERIC_READ,0,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);

      if(locked==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot lock test-owned preference file");

      const bool applied=applyPreferences();CloseHandle(locked);

      if(applied || pending_!=Pending::Preferences || runtimePreferences_.values!=saved || preferenceFeedback_.find(U"editor-preferences.txt")==std::u32string::npos)throw std::runtime_error("Preference disk failure lost dialog, settings or error detail");

      if(!applyPreferences())throw std::runtime_error("Preference retry after disk failure failed");

    }

    auto bars=dynamic_cast<PixelSwitch*>(row("editing.canvasViewScrollbarsEnabled"));

    if(!bars || !bars->isEnabled())throw std::runtime_error("Canvas scrollbar preference unavailable");

    const bool before=runtimePreferences_.flag("editing.canvasViewScrollbarsEnabled");bars->Click();

    if(runtimePreferences_.flag("editing.canvasViewScrollbarsEnabled")!=before || runtimePreferenceDraft_.flag("editing.canvasViewScrollbarsEnabled")==before)throw std::runtime_error("Preference draft leaked or switch callback lost");

    resolve(false);showPreferences();preferenceTabs_[5]->Click();if(bars->checked()!=before)throw std::runtime_error("Cancelled preference retained");

    bars->Click();preferenceApply_->Click();if(runtimePreferences_.flag("editing.canvasViewScrollbarsEnabled")==before || pending_!=Pending::Preferences)throw std::runtime_error("Preference Apply failed: "+utf8Text(status_));

    if(!runtimePreferences_.flag("editing.canvasViewScrollbarsEnabled") && canvasViewport()!=canvasFullViewport())throw std::runtime_error("Scrollbar setting did not reach canvas geometry");

    resolve(false);showPreferences();preferenceTabs_[5]->Click();if(bars->checked()==before)throw std::runtime_error("Applied preference lost on reopen");

    auto wheel=dynamic_cast<PixelSwitch*>(row("editing.wheelZoomEnabled"));wheel->Click();

    if(row("editing.wheelZoomMode.Select")->isEnabled()==runtimePreferenceDraft_.flag("editing.wheelZoomEnabled")){}else throw std::runtime_error("Dependent preference enabled state");

    preferenceTabs_[4]->Click();auto custom=dynamic_cast<PixelDropdown*>(row("cursor.selectionPreviewColorMode.Select"));custom->setSelectedIndex(1,true);

    auto color=dynamic_cast<PixelEntry*>(row("cursor.selectionPreviewColor.Color"));color->setText("bad");if(applyPreferences())throw std::runtime_error("Invalid color preferences saved");

    for(auto size:{gfx::Size(720,600),gfx::Size(1280,960)}){setBounds(gfx::Rect(size));refresh();const auto modal=modalBounds(uiLogical(clientBounds()));const auto feedback=preferenceFeedbackBounds(modal);if(preferenceBodyBounds(modal).y2()+6>feedback.y || feedback.y2()+6>modalActionY(modal) || !modal.contains(feedback))throw std::runtime_error("Preference feedback overlaps content or buttons");

      if(persist){auto surface=os::instance()->makeRgbaSurface(size.w,size.h);surface->clear();{ui::Graphics g(surface);ui::PaintEvent event(this,&g);onPaint(event);paintDialog(g);}for(auto child:children())if(!child->hasFlags(ui::HIDDEN) && modalControl(child)){ui::Graphics g(nullptr,surface,child->bounds().x,child->bounds().y);g.saveClip();g.clipRect(child->clientBounds());ui::PaintEvent ev(child,&g);if(auto button=dynamic_cast<PixelButton*>(child))button->onPaint(ev);else if(auto entry=dynamic_cast<PixelEntry*>(child))entry->onPaint(ev);g.restoreClip();}writeSmokeFrame(surface.get(),recoveryDirectory_.parent_path()/("feedback-"+std::to_string(size.w)+".bmp"));}

    }

    color->setText("#123456");if(!applyPreferences())throw std::runtime_error("Valid color preferences rejected");

    if(selectionPreviewColor(0,0)!=gfx::rgba(0x12,0x34,0x56,255))throw std::runtime_error("Selection preference did not affect preview renderer");

    if(persist){std::ifstream input(palettePreferencePath().parent_path()/"editor-preferences.txt",std::ios::binary);if(preferences::RuntimeSettings::decode(input).values!=runtimePreferences_.values)throw std::runtime_error("Preferences disk roundtrip failed");}

    resolve(false);if(document.historySize()!=history || document.revision()!=revision || document.pixels()!=pixels)throw std::runtime_error("Preferences changed document history");

    runtimePreferences_=original;refresh();

  }

void Editor::smokePreferenceCatalog(const std::filesystem::path& directory,const std::function<bool(ui::MouseMessage&)>& wheelDispatch){

    smoke_=true;homeOpen_=false;documentOpen_=true;pending_=Pending::None;setBounds(gfx::Rect(0,0,1280,960));refresh();showPreferences();

    const auto pixels=document.pixels();const auto history=document.historySize();

    if(preferenceRows_.size()!=preferences::catalog().size())throw std::runtime_error("Missing preference controls");

    for(auto size:{gfx::Size(720,600),gfx::Size(1280,960)}){

      setBounds(gfx::Rect(size));refresh();

      for(int section=0;section<14;++section){preferenceTabs_[section]->Click();

        const int height=preferenceCatalogHeight();

        for(int offset=0;offset<height*uiScale;offset+=std::max(1,preferenceViewport_.h)){

          preferenceContentPixels_=offset;layoutModal();int visible=0;

          for(std::size_t i=0;i<preferenceRows_.size();++i){const auto& item=preferences::catalog()[i];auto field=preferenceRows_[i];

            if(field->hasFlags(ui::HIDDEN))continue;

            if(item.section!=section || field->isEnabled()!=preferenceRowEnabled(item))throw std::runtime_error("Preference page visibility or disabled contract");

            if((field->bounds()&preferenceViewport_).isEmpty())throw std::runtime_error("Unclipped preference row");

            if(!modalControl(field))throw std::runtime_error("Preference excluded from modal interaction");

            if(item.kind==preferences::Kind::Toggle){const auto toggle=dynamic_cast<PixelSwitch*>(field);if(!toggle || toggle->caption!=item.label || field->bounds().x!=preferenceViewport_.x+2*uiScale || field->bounds().w!=preferenceViewport_.w-6*uiScale)throw std::runtime_error("Preference toggle must contain its own label and span the row");}

            if(item.binding<0 && dynamic_cast<PixelEntry*>(field) && static_cast<PixelEntry*>(field)->hasFocus())throw std::runtime_error("Unavailable field focused");

            ++visible;

          }

          if(!visible)throw std::runtime_error("Preference page has no component rows");

        }

        preferenceContentPixels_=0;layoutModal();

        if(size.w==1280){

          auto surface=os::instance()->makeRgbaSurface(size.w,size.h);surface->clear();

          {ui::Graphics g(surface);ui::PaintEvent event(this,&g);onPaint(event);paintDialog(g);}

          for(auto child:children())if(!child->hasFlags(ui::HIDDEN) && modalControl(child)){

            ui::Graphics g(nullptr,surface,child->bounds().x,child->bounds().y);g.saveClip();g.clipRect(child->clientBounds());ui::PaintEvent ev(child,&g);

            if(auto button=dynamic_cast<PixelButton*>(child))button->onPaint(ev);else if(auto entry=dynamic_cast<PixelEntry*>(child))entry->onPaint(ev);g.restoreClip();

          }

          writeSmokeFrame(surface.get(),directory/("preferences-section-"+std::to_string(section)+".bmp"));

        }

      }

    }

    auto wheel=[&](gfx::Point point,int steps){ui::MouseMessage event(ui::kMouseWheelMessage,os::PointerType::Mouse,ui::kButtonNone,ui::kKeyNoneModifier,point,gfx::Point(0,steps));return wheelDispatch(event);};

    for(auto size:{gfx::Size(720,600),gfx::Size(1280,960)}){

      setBounds(gfx::Rect(size));refresh();preferenceTabs_[0]->Click();

      const auto viewport=preferenceViewport_;const auto modal=modalBounds(uiLogical(clientBounds()));

      std::vector<gfx::Point> points{viewport.origin()+gfx::Point(2,2),viewport.center(),preferenceContentBar_->bounds().center(),toDisplay(gfx::Rect(modal.x+94,modal.y+25,1,1)).origin()};

      for(auto field:preferenceRows_)if(!field->hasFlags(ui::HIDDEN))points.push_back((field->bounds()&viewport).center());

      for(auto point:points){preferenceContentPixels_=0;layoutModal();

        if(!wheel(point,1) || preferenceContentPixels_!=24*uiScale)throw std::runtime_error("Preferences wheel-down/container routing");

        if(!wheel(point,-1) || preferenceContentPixels_!=0)throw std::runtime_error("Preferences wheel-up direction");

        wheel(point,3);if(preferenceContentPixels_!=72*uiScale)throw std::runtime_error("Preferences batched wheel delta lost");

      }

      preferenceTabs_[2]->Click();const auto checkerSize=checkerboardFields_[0]->text();

      if(!wheel(checkerboardFields_[0]->bounds().center(),1) || preferenceContentPixels_==0 || checkerboardFields_[0]->text()!=checkerSize)throw std::runtime_error("Preferences numeric entry consumed container wheel");

      const int before=preferenceContentPixels_;wheel(toDisplay(gfx::Rect(modal.x,modal.y,1,1)).origin(),1);

      if(preferenceContentPixels_!=before)throw std::runtime_error("Preferences scrolled outside container");

      wheel(preferenceContentBar_->bounds().center(),10000);const int bottom=preferenceContentPixels_;wheel(preferenceContentBar_->bounds().center(),1);

      if(preferenceContentPixels_!=bottom)throw std::runtime_error("Preferences bottom clamp");

      wheel(preferenceContentBar_->bounds().center(),-10000);if(preferenceContentPixels_!=0)throw std::runtime_error("Preferences top clamp");

      {const auto navPoint=preferenceTabs_[0]->bounds().center();wheel(navPoint,1);if((preferenceNavBar_->isVisible() && preferenceNavPixels_<=0) || preferenceContentPixels_!=0)throw std::runtime_error("Preferences navigation wheel routing");wheel(navPoint,-1);if(preferenceNavPixels_!=0)throw std::runtime_error("Preferences navigation up wheel");}

    }

    setBounds(gfx::Rect(0,0,800,360));modalGeometry_[Pending::Preferences]=gfx::Rect(10,10,350,150);preferenceNavPixels_=preferenceContentPixels_=0;layoutModal();

    const auto navPoint=preferenceTabs_[0]->bounds().center();

    if(!wheel(navPoint,1) || preferenceNavPixels_!=15*uiScale || preferenceContentPixels_!=0)throw std::runtime_error("Preferences overflowing navigation down wheel");

    wheel(navPoint,-1);if(preferenceNavPixels_!=0)throw std::runtime_error("Preferences overflowing navigation up wheel");

    resolve(false);for(auto field:preferenceRows_)if(!field->hasFlags(ui::HIDDEN))throw std::runtime_error("Closed preferences leaked row controls");

    if(document.pixels()!=pixels || document.historySize()!=history)throw std::runtime_error("Preferences changed artwork");

  }

void Editor::smokeCheckerboardPreferences(){

    smoke_=true;homeOpen_=false;documentOpen_=true;pending_=Pending::None;setBounds(gfx::Rect(0,0,1280,960));refresh();

    const auto before=checkerboard_;const auto history=document.historySize();const auto pixels=document.pixels();

    showPreferences();preferenceTabs_[2]->Click();

    for(auto field:checkerboardFields_)if(field->hasFlags(ui::HIDDEN) || !modalControl(field))throw std::runtime_error("Checker preferences not interactive");

    checkerboardFields_[0]->setText("32");checkerboardFields_[0]->Change();

    checkerboardFields_[1]->setText("#123456");checkerboardFields_[1]->Change();

    if(checkerboard_.size!=before.size || checkerboard_.light!=before.light)throw std::runtime_error("Checker draft leaked before Apply");

    resolve(false);if(checkerboard_.size!=before.size || checkerboard_.light!=before.light)throw std::runtime_error("Checker Cancel changed preferences");

    showPreferences();preferenceTabs_[2]->Click();checkerboardFields_[0]->setText("300");checkerboardFields_[0]->Change();checkerboardFields_[1]->setText("#123456");checkerboardFields_[1]->Change();

    if(!applyPreferences() || checkerboard_.size!=256 || checkerboard_.light!=gfx::rgba(0x12,0x34,0x56) || previewPanel_->checkerboard.light!=checkerboard_.light)throw std::runtime_error("Checker Apply/size clamp/preview sync");

    resolve(false);for(auto field:checkerboardFields_)if(!field->hasFlags(ui::HIDDEN))throw std::runtime_error("Checker fields leaked from dialog");

    if(document.historySize()!=history || document.pixels()!=pixels)throw std::runtime_error("Checker changed document");

    checkerboard_=before;previewPanel_->checkerboard=before;refresh();

  }

