    smoke_=true;homeOpen_=false;documentOpen_=true;requestFocus();refresh();const auto pixels=document.pixels();const auto history=document.historySize();const bool dirty=document.dirty(),smooth=navigation_.zoomSmooth_,lens=eyedropperLensEnabled_;const auto original=bounds();

