    for(auto size:{gfx::Size(720,600),gfx::Size(1280,960)}){setBounds(gfx::Rect(original.origin(),size));refresh();const auto modal=dialogDisplayBounds();for(auto tab:preferenceTabs_)if(!tab->hasFlags(ui::HIDDEN) && !modal.contains(tab->bounds()))throw std::runtime_error("Preferences sidebar escaped viewport visible="+std::to_string(tab->isVisible())+" tab="+std::to_string(tab->bounds().x)+","+std::to_string(tab->bounds().y)+","+std::to_string(tab->bounds().w)+","+std::to_string(tab->bounds().h)+" modal="+std::to_string(modal.x)+","+std::to_string(modal.y)+","+std::to_string(modal.w)+","+std::to_string(modal.h));for(auto field:preferenceFields_)if(!field->hasFlags(ui::HIDDEN)&&!(field->bounds()&preferenceViewport_).isEmpty()&&!modal.contains(field->bounds()&preferenceViewport_))throw std::runtime_error("Preferences field escaped viewport");if(!modal.contains(preferenceApply_->bounds()) || !bounds().contains(modal))throw std::runtime_error("Preferences actions escaped viewport");}

