    while(std::chrono::steady_clock::now()<deadline){recoveryTick(true);if(!recovery_.worker.valid() && !recovery_.snapshot && std::all_of(projects_.begin(),projects_.end(),[](const auto& slot){return !slot->recovery.worker.valid() && !slot->recovery.snapshot;}))break;std::this_thread::sleep_for(std::chrono::milliseconds(5));}

