      auto pixel=[&]{auto frame=os::instance()->makeRgbaSurface(box.bounds().w,box.bounds().h);frame->clear();ui::Graphics g(frame);ui::PaintEvent e(&box,&g);box.onPaint(e);return frame->getPixel(0,2*uiScale);};

