    selectionTool_=true;selectionKind_=0;selectionShift_=selectionCtrl_=spaceHeld_=handTool_=eyedropperTool_=eyedropperHeld_=false;

    setBounds({0,0,1280,960});document.deselectPixels();refresh();fitCanvas();refresh();

    const auto pointer=canvasViewport().center();updatePaletteMouse(pointer);

    if(!selectionPointerVisible(pointer)||selectionPointerDamage_.isEmpty())throw std::runtime_error("Selection pointer missing on canvas: owner="+std::to_string(canvasOwnsPointer(pointer))+" cursor="+cursorAt(pointer)+" hitEditor="+std::to_string(frontWidgetAt(pointer)==this)+" capture="+std::to_string(ui::Manager::getDefault()->getCapture()!=nullptr));

    const auto history=document.historySize();

