    if(selectionPointerVisible(pointer)||!selectionPointerDamage_.isEmpty()||std::string(cursorAt(pointer))!="default")throw std::runtime_error("Selection pointer leaked through overlay");

    ui::MouseMessage uiDown(ui::kMouseDownMessage,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,pointer);

    onProcessMessage(&uiDown);

