void Editor::smokeStaticExport(){

    smoke_=true;setBounds(gfx::Rect(0,0,1280,960));document=Document(3,2);homeOpen_=false;documentOpen_=true;refresh();

    const auto h=document.historySize(),rev=document.revision();openStaticExport();

    if(exportScaleInput_->hasFlags(ui::HIDDEN)||exportOptions_.scalePercent!=100||exportOptions_.trim)throw std::runtime_error("Static export defaults/UI");

    auto checkLayout=[&](const char* filename){

      const auto modal=dialogDisplayBounds();

      if(exportFormatButton_->bounds().y!=exportLayerButton_->bounds().y || keep_->bounds().x2()>exportOpenFolderButton_->bounds().x || exportOpenFolderButton_->bounds().x2()>discard_->bounds().x || discard_->bounds().y2()>modal.y2()-6*uiScale)

        throw std::runtime_error("Legacy export field/footer alignment");

      for(auto b:exportScaleButtons_)if(!modal.contains(b->bounds()) || !modalControl(b))throw std::runtime_error("Export presets outside modal or blocked");

      auto surface=os::instance()->makeRgbaSurface(bounds().w,bounds().h);surface->clear();

      {ui::Graphics g(surface);ui::PaintEvent ev(this,&g);onPaint(ev);paintDialog(g);}

      for(auto child:children())if(!child->hasFlags(ui::HIDDEN) && modalControl(child)){

        ui::Graphics g(nullptr,surface,child->bounds().x,child->bounds().y);g.saveClip();g.clipRect(child->clientBounds());ui::PaintEvent ev(child,&g);if(auto dropdown=dynamic_cast<PixelDropdown*>(child))dropdown->PixelDropdown::onPaint(ev);else if(auto b=dynamic_cast<PixelButton*>(child))b->PixelButton::onPaint(ev);else if(auto e=dynamic_cast<PixelEntry*>(child))e->PixelEntry::onPaint(ev);g.restoreClip();

      }

      writeSmokeFrame(surface.get(),assets_.parent_path()/filename);

    };

    if(!dynamic_cast<PixelDropdown*>(exportFormatButton_)||!dynamic_cast<PixelDropdown*>(exportLayerButton_)||!dynamic_cast<PixelDropdown*>(exportTrimButton_)||!dynamic_cast<PixelDropdown*>(gifRange_)||!dynamic_cast<PixelDropdown*>(gifDirection_))throw std::runtime_error("Export selectors must use dropdown components");

    const auto savedPresets=savedExportPresets_;const bool readable=exportPresetsReadable_;const auto presetName=exportPresets_.name->text();

    exportPresetPathOverride_=assets_.parent_path()/"export-presets-test-owned"/(std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64()))/"presets.txt";

    struct PresetRestore{std::function<void()> fn;~PresetRestore(){fn();}} restorePresets{[&]{exportPresetPathOverride_.clear();savedExportPresets_=savedPresets;exportPresetsReadable_=readable;exportPresets_.name->setText(presetName);exportPresetFeedback_.clear();updateExportPresetOptions();}};

    savedExportPresets_.clear();exportPresetsReadable_=true;updateExportPresetOptions();

    checkLayout("export-dialog-static.bmp");

    if(exportFilename_->hasFlags(ui::HIDDEN)||exportLocation_->hasFlags(ui::HIDDEN)||!modalControl(exportFilename_)||!modalControl(exportLocation_))throw std::runtime_error("Export location components missing");

    if(exportLocation_->bounds().x-exportFilename_->bounds().x2()!=2*uiScale ||

       exportLayerButton_->bounds().x-exportFormatButton_->bounds().x2()!=2*uiScale ||

       discard_->bounds().x-exportOpenFolderButton_->bounds().x2()!=2*uiScale)

      throw std::runtime_error("Export related controls must have a 2px gap");

    auto picker=chooseExportFile_;chooseExportFile_=[&](OPENFILENAMEW* d){auto value=(exportPresetPathOverride_.parent_path()/L"chosen.png").wstring();std::copy(value.begin(),value.end(),d->lpstrFile);d->lpstrFile[value.size()]=0;return true;};

    chooseExportLocation();chooseExportFile_=picker;exportFilename_->setText("renamed.png");

    wchar_t pathBuffer[32768]{};OPENFILENAMEW pathDialog{};pathDialog.lpstrFile=pathBuffer;pathDialog.nMaxFile=32768;

    std::filesystem::create_directories(exportDirectory_);

    if(!chooseFormExportFile(&pathDialog)||std::filesystem::path(pathBuffer)!=exportDirectory_/L"renamed.png")throw std::runtime_error("Export form path ignored");

    for(int i=1;i<4;++i)if(exportScaleButtons_[i-1]->bounds().x2()-exportScaleButtons_[i]->bounds().x!=uiScale)throw std::runtime_error("Scale group border not shared");

    exportScaleButtons_[2]->Click();

    if(exportScaleInput_->text()!="400" || exportOptions_.scalePercent!=400)throw std::runtime_error("Export scale preset did not sync draft");

    exportPresets_.name->setText("smoke-layout-owned");saveExportPreset();loadExportPresets();updateExportPresetOptions();

    if(savedExportPresets_.size()!=1 || savedExportPresets_[0].image.scalePercent!=400)throw std::runtime_error("Export preset save/reload");

    exportScaleButtons_[0]->Click();exportPresets_.choices->setSelectedIndex(0);exportPresets_.choices->setSelectedIndex(1,true);

    if(exportOptions_.scalePercent!=400 || exportScaleInput_->text()!="400")throw std::runtime_error("Export preset apply");

    deleteExportPreset();loadExportPresets();if(!savedExportPresets_.empty())throw std::runtime_error("Export preset delete/reload");

    auto out=encodeStaticImagePng(document,exportOptions_);if(out.width!=12||out.height!=8)throw std::runtime_error("Static export percentage");resolve(false);

    openGifExport();gifExplicitRange_=true;refresh();checkLayout("export-dialog-animation.bmp");

    if(gifInputs_[1]->bounds().y2()>=gifDirection_->bounds().y || gifDirection_->bounds().y2()>=gifInputs_[0]->bounds().y || gifInputs_[0]->bounds().y2()>=gifTrim_->bounds().y || gifTrim_->bounds().y2()>=keep_->bounds().y)

      throw std::runtime_error("Animation export groups overlap");

    exportScaleButtons_[2]->Click();if(gifOptions_.scalePercent!=400 || gifInputs_[0]->text()!="400")throw std::runtime_error("Animation scale preset did not sync draft");

    resolve(false);if(document.historySize()!=h||document.revision()!=rev||document.dirty())throw std::runtime_error("Static export cancel mutation");document=Document();refresh();

  }

