void Editor::smokeAdjustmentComponents(){

    smokeColorAdjustments();smoke_=true;setBounds({0,0,1280,960});homeOpen_=false;documentOpen_=true;document=Document(2,1);refresh();

    for(auto kind:{ColorAdjustmentKind::BrightnessContrast,ColorAdjustmentKind::HueSaturation,ColorAdjustmentKind::ColorBalance,ColorAdjustmentKind::Curves,ColorAdjustmentKind::GradientMap}){

      if(kind==ColorAdjustmentKind::GradientMap)openGradientMap();else openColorAdjustment(kind);

      if(kind!=ColorAdjustmentKind::Curves&&kind!=ColorAdjustmentKind::GradientMap){

        for(int i=0;i<2;++i){const auto slider=adjustmentSliders_[i]->bounds(),entry=adjustmentInputs_[i]->bounds();if(slider.h!=textControlHeight*uiScale||slider.y!=entry.y||slider.h!=entry.h)throw std::runtime_error("Slider normal material/input alignment");}

        if(kind==ColorAdjustmentKind::ColorBalance){for(int i=1;i<3;++i)if(adjustmentToneButtons_[i]->bounds().x!=adjustmentToneButtons_[i-1]->bounds().x2()-uiScale)throw std::runtime_error("Tone buttons must share one border");if(adjustmentPreview_->bounds().y-adjustmentColorize_->bounds().y2()!=2*uiScale)throw std::runtime_error("Adjustment option gap");}

        adjustmentSliders_[0]->changed(20);

        if(adjustmentInputs_[0]->text()!="20"||adjustmentSliders_[0]->value!=20)throw std::runtime_error("Adjustment slider/input binding");

        adjustmentInputs_[1]->setText("35");adjustmentInputs_[1]->Change();

        if(adjustmentSliders_[1]->value!=35)throw std::runtime_error("Adjustment input/slider binding");

        if(kind==ColorAdjustmentKind::HueSaturation){adjustmentColorize_->Click();if(adjustmentSliders_[0]->minimum!=0||adjustmentSliders_[0]->maximum!=360||adjustmentSliders_[1]->minimum!=0||!adjustmentColorize_->active)throw std::runtime_error("Colorize slider domain");}

      }

      const auto modal=dialogDisplayBounds();

      for(auto child:children())if(modalControl(child)&&!child->hasFlags(ui::HIDDEN)){

        if(!modal.contains(child->bounds()))throw std::runtime_error("Adjustment component outside dialog");

        if(child!=discard_&&child!=keep_&&child!=dialogClose_&&child->bounds().y2()>discard_->bounds().y)throw std::runtime_error("Adjustment content overlaps footer");

      }

      if(!dynamic_cast<PixelSwitch*>(adjustmentPreview_)||!adjustmentColorize_->isCheckbox())throw std::runtime_error("Adjustment shared toggle components");

      auto surface=os::instance()->makeRgbaSurface(bounds().w,bounds().h);surface->clear();

      {ui::Graphics g(surface);ui::PaintEvent ev(this,&g);onPaint(ev);paintDialog(g);}

      for(auto child:children())if(modalControl(child)&&!child->hasFlags(ui::HIDDEN)){

        ui::Graphics g(nullptr,surface,child->bounds().x,child->bounds().y);g.saveClip();g.clipRect(child->clientBounds());ui::PaintEvent ev(child,&g);

        if(auto slider=dynamic_cast<PixelSlider*>(child))slider->PixelSlider::onPaint(ev);

        else if(auto button=dynamic_cast<PixelButton*>(child))button->PixelButton::onPaint(ev);

        else if(auto entry=dynamic_cast<PixelEntry*>(child))entry->PixelEntry::onPaint(ev);

        else if(auto curve=dynamic_cast<CurveEditorNative*>(child))curve->onPaint(ev);

        g.restoreClip();

      }

      writeSmokeFrame(surface.get(),assets_.parent_path()/("adjustment-components-"+std::to_string(int(kind))+".bmp"));

      resolve(false);

    }

    document=Document();refresh();

  }

