    auto popup=colorEditorPopup_.get();auto surface=os::instance()->makeRgbaSurface(popup->bounds().w,popup->bounds().h);surface->clear();{ui::Graphics g(surface);ui::PaintEvent ev(popup,&g);popup->onPaint(ev);}

    for(auto child:popup->children())if(child->isVisible()){const auto at=child->bounds().origin()-popup->bounds().origin();ui::Graphics g(nullptr,surface,at.x,at.y);ui::PaintEvent ev(child,&g);if(auto e=dynamic_cast<PixelEntry*>(child))e->onPaint(ev);else if(auto b=dynamic_cast<PixelButton*>(child))b->onPaint(ev);else if(auto slider=dynamic_cast<PixelSlider*>(child))slider->onPaint(ev);}

    writeSmokeFrame(surface.get(),assets_.parent_path()/"color-editor-smoke.bmp");popup->closeWindow(nullptr);if(document.palette().primary!=0x80332211)throw std::runtime_error("Closing editor reverted live color");

